import { showConfetti } from "./confetti";
import { logVerbose } from "./logVerbose";

export const BUTTON_BASE_CLASS = "brighthire-button";
export const BUTTON_TEXT_CLASS = "bh-button-text";
const IMPORT_ALL_BUTTON_ID = "bh-import-all";

/**
 * Delay between field insertions to avoid ATS auto-save race conditions.
 * Use setImportAllDelay(0) in tests to avoid waiting.
 */
let importAllDelayMs = 300;

export const getImportAllDelay = (): number => importAllDelayMs;
export const setImportAllDelay = (ms: number): void => {
  importAllDelayMs = ms;
};

type ButtonType = "primary" | "secondary";

interface CreateButtonOptions {
  parent?: Element;
  /** Custom logic for inserting the button. Default behavior is to append the button to `parent` */
  insertBtn?(btn: HTMLButtonElement): void;
  text: string;
  type?: ButtonType;
  size?: "sm";
  disabled?: boolean;
  cssClass?: string | string[];
  style?: Record<string, string>;
  includeImage?: boolean;
  onClick?: (e: MouseEvent) => void;
}

export function createButton({
  parent,
  insertBtn,
  text,
  type: buttonType = "primary",
  size,
  disabled,
  cssClass,
  style,
  includeImage = true,
  onClick: onclick,
}: CreateButtonOptions): HTMLButtonElement {
  parent?.querySelector<HTMLButtonElement>(`.${BUTTON_BASE_CLASS}`)?.remove();
  const button = document.createElement("button");

  button.type = "button";

  const textEl = document.createElement("span");
  textEl.innerText = text;
  textEl.classList.add(BUTTON_TEXT_CLASS);
  button.appendChild(textEl);

  button.classList.add(BUTTON_BASE_CLASS);
  if (Array.isArray(cssClass)) button.classList.add(...cssClass);
  else if (typeof cssClass === "string") button.classList.add(cssClass);
  if (size === "sm") button.classList.add("bh-small");

  button.disabled = disabled ?? false;

  if (includeImage) {
    button.insertBefore(
      createButtonImage(buttonType, button.disabled),
      button.firstChild,
    );
  }

  styleButton(buttonType, button, style);

  if (onclick) button.onclick = onclick;

  if (insertBtn) {
    insertBtn(button);
  } else if (parent) {
    parent.appendChild(button);
  }

  return button;
}

export interface CreateCopyButtonOptions {
  parent?: Element;
  insertBtn?(btn: HTMLButtonElement): void;
  text?: string;
  id?: string;
  type: ButtonType;
  disabled?: boolean;
  noteCount: number;
  cssClass?: string | string[];
  style?: Record<string, string>;
  isLoading?: boolean;
  onClick?: (e: MouseEvent) => void;
}

export function removeAllButtons(parent?: Element | null): void {
  logVerbose("removeAllButtons");
  const buttons = (parent || document).getElementsByClassName(
    BUTTON_BASE_CLASS,
  );
  let failSafe = 0;

  while (buttons.length && failSafe < 1_000) {
    buttons.item(0)?.dispatchEvent(new Event("remove"));
    buttons.item(0)?.remove();
    failSafe += 1;
  }
}

export function createCopyButton({
  parent,
  insertBtn,
  text,
  id,
  type: buttonType,
  disabled,
  noteCount,
  cssClass,
  style,
  isLoading,
  onClick: onclick,
}: CreateCopyButtonOptions): HTMLButtonElement {
  // biome-ignore lint/complexity/noArguments: previously suppressed via eslint (prefer-rest-params)
  logVerbose("createCopyButton", ...arguments);
  parent?.querySelector(id ? `#${id}` : `.${BUTTON_BASE_CLASS}`)?.remove();
  const button = document.createElement("button");

  button.type = "button";
  if (id) button.id = id;

  let buttonText = `Import ${noteCount} note${noteCount === 1 ? "" : "s"}`;
  if (isLoading) {
    buttonText = "Loading...";
  } else if (text) {
    buttonText = text;
  } else if (noteCount === 0) {
    buttonText = "No matching notes";
  }
  const textEl = document.createElement("span");
  textEl.innerText = buttonText;
  textEl.classList.add(BUTTON_TEXT_CLASS);
  button.appendChild(textEl);

  button.classList.add(BUTTON_BASE_CLASS);
  if (Array.isArray(cssClass)) button.classList.add(...cssClass);
  else if (typeof cssClass === "string") button.classList.add(cssClass);

  button.disabled = disabled ?? noteCount === 0;

  if (isLoading) {
    const loader = document.createElement("div");
    loader.style.cssText = `
      height: 1em;
      width: 1em;
      margin-right: 8px;
      border-radius: 100%;
      border: 2px solid #0772D0;
      border-left-color: transparent;
      border-bottom-color: transparent;
      animation: bh-spin 700ms linear infinite;
    `;
    button.insertBefore(loader, button.firstChild);
  } else {
    button.insertBefore(
      createButtonImage(buttonType, button.disabled),
      button.firstChild,
    );
  }
  styleButton(buttonType, button, style);

  if (onclick) button.onclick = onclick;

  if (insertBtn) {
    insertBtn(button);
  } else if (parent) {
    parent.appendChild(button);
  }

  return button;
}

type CreateCopyAllButtonOptions = Pick<
  CreateCopyButtonOptions,
  "style" | "insertBtn" | "parent" | "onClick"
>;

export function createCopyAllButton(
  payload: Pick<FillScorecardPayload, "showConfetti" | "autofill">,
  opts: CreateCopyAllButtonOptions,
  isLoading?: boolean,
): HTMLButtonElement {
  logVerbose("createCopyAllButton", payload, opts);
  const copyAllClass = "bh-fill-all";

  const hasNotes = !!document.querySelector(
    `.${BUTTON_BASE_CLASS}:not(.${copyAllClass}):not([disabled])`,
  );

  const button = createCopyButton({
    ...opts,
    noteCount: -1,
    text: "Import all notes",
    id: IMPORT_ALL_BUTTON_ID,
    type: "primary",
    disabled: !hasNotes,
    cssClass: copyAllClass,
    isLoading,
    onClick: async (e) => {
      // Click each button with a delay to avoid ATS auto-save race conditions.
      // Some ATSes (like Ashby) save each field individually but the mutation
      // re-renders the whole form, so rapid updates can cause fields to revert.
      const buttons = Array.from(
        document.querySelectorAll<HTMLElement>(`.${BUTTON_BASE_CLASS}`),
      ).filter((el) => el !== button);

      for (const el of buttons) {
        el.click();
        if (importAllDelayMs > 0) {
          await new Promise((resolve) => {
            setTimeout(resolve, importAllDelayMs);
          });
        }
      }

      if (payload.showConfetti) showConfetti();
      opts.onClick?.(e);
    },
  });

  if (payload.autofill) {
    button.dispatchEvent(new Event("click"));
  } else if (hasNotes) {
    button.classList.add("bh-shine");
  }

  return button;
}

export const checkButtonText = (
  btn: HTMLButtonElement,
  hasNotes: boolean,
): void => {
  const textEl = btn.querySelector(`.${BUTTON_TEXT_CLASS}`) as HTMLElement;
  if (hasNotes) {
    textEl.innerText = textEl.innerText.replace("Import", "Append");
  } else {
    textEl.innerText = textEl.innerText.replace("Append", "Import");
  }
};

/*
  Helpers
*/

function createButtonImage(
  type: ButtonType,
  disabled?: boolean,
): HTMLImageElement {
  logVerbose("createButtonImage", type);
  const img = new Image();
  img.src = "https://app.brighthire.ai/static/images/logo_ui.svg";

  const styles: Record<string, string> = {
    height: "1rem",
    width: "1rem",
    marginRight: "4px",
  };

  if (type === "primary") {
    styles.filter = "brightness(0) invert(1)";
    styles.height = "18px";
    styles.width = "18px";
  } else if (disabled) {
    styles.filter = "brightness(0) invert(0.75)";
  }

  Object.entries(styles).forEach(([key, val]) => {
    img.style[key as any] = val;
  });

  return img;
}

function styleButton(
  buttonType: ButtonType,
  button: HTMLButtonElement,
  style?: Record<string, string>,
): void {
  const btn = button;
  btn.classList.add(`bh-${buttonType}`);

  const styles = {
    display: "flex",
    alignItems: "center",
    ...style,
  };

  Object.entries(styles).forEach(([key, val]) => {
    btn.style[key as any] = val;
  });
}
