import { createButton } from "../../utils/button";
import { showConfetti } from "../../utils/confetti";
import { MutationSummary } from "../../utils/MutationSummary";
import {
  addPassiveMessageListener,
  sendMessageWithTabId,
} from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { initSentry } from "../../utils/sentry";
import { escapeHtml } from "../../utils/string";

initSentry();

/**
 * Workday Candidate Notes Content Script
 *
 * Detects the "Add Note: Job Application" side panel on Workday candidate
 * pages and injects a single "Import BrightHire Notes" button next to
 * the "Description" label, allowing interviewers to pull AI-generated
 * notes into the rich text editor with one click.
 *
 * Flow:
 * 1. Find the "Description" label inside the Add Note panel
 * 2. Inject one "Import BrightHire Notes" button as a sibling after it
 * 3. On click, send `pullCandidateNotes` to the sidepanel (via service worker)
 * 4. The sidepanel fetches AI notes and sends back `fillCandidateNotes`
 * 5. This script finds the rich text editor and pastes the notes in
 */

const BUTTON_CONTAINER_CLASS = "bh-candidate-notes-btn";

/** Reference to the single injected button */
let importButton: HTMLButtonElement | null = null;

/** Guard to prevent re-entrant DOM manipulation from the MutationSummary observer */
let isUpdatingDom = false;

/** Whether the sidepanel has an interview selected and ready for import */
let interviewSelected = false;

/**
 * Find the "Add Note" panel container. Workday renders this as a side
 * panel with a header like "Add Note: Job Application" or similar.
 */
const findAddNotePanel = (): HTMLElement | null => {
  // Look for elements whose text starts with "Add Note"
  const allElements = document.querySelectorAll<HTMLElement>(
    '[data-automation-id="pageHeaderTitleText"], [role="heading"], h1, h2, h3',
  );

  for (const el of allElements) {
    const text = (el.textContent ?? "").trim();
    if (/^Add Note/i.test(text)) {
      // Walk up to find the panel container
      let container: HTMLElement | null = el;
      for (let i = 0; i < 6 && container; i++) {
        container = container.parentElement;
      }
      return container;
    }
  }

  return null;
};

/**
 * Find the "Description" label element inside the Add Note panel.
 * This is the anchor point where we inject our button.
 */
const findDescriptionLabel = (): HTMLElement | null => {
  const panel = findAddNotePanel();
  if (!panel) return null;

  // Look for label-like elements with text "Description"
  const candidates = panel.querySelectorAll<HTMLElement>(
    "label, legend, [data-automation-id]",
  );
  for (const el of candidates) {
    const text = getDirectText(el).trim();
    if (/^Description\s*\*?$/.test(text)) {
      return el;
    }
  }

  // Broader fallback within the panel
  const allElements = panel.querySelectorAll<HTMLElement>("*");
  for (const el of allElements) {
    // Only match leaf-ish elements (not deep containers)
    if (el.children.length <= 2) {
      const text = (el.textContent ?? "").trim();
      if (/^Description\s*\*?$/.test(text)) {
        return el;
      }
    }
  }

  return null;
};

/**
 * Get only the direct text content of an element (text nodes that are
 * immediate children), ignoring text from nested child elements.
 */
const getDirectText = (el: HTMLElement): string => {
  let text = "";
  el.childNodes.forEach((node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      text += node.textContent ?? "";
    }
  });
  return text;
};

/**
 * Find the rich text editor input in the Add Note panel.
 * Workday uses a contenteditable div with a formatting toolbar.
 */
const findNoteInput = (): HTMLElement | null => {
  const panel = findAddNotePanel();
  if (!panel) return null;

  // Try contenteditable first (Workday rich text editor)
  const editable = panel.querySelector<HTMLElement>('[contenteditable="true"]');
  if (editable) return editable;

  // Fallback to textarea within the panel
  const textarea = panel.querySelector<HTMLTextAreaElement>(
    "textarea:not([readonly])",
  );
  if (textarea) return textarea;

  return null;
};

/**
 * Convert plain text to HTML paragraphs for rich text editors.
 * Each non-empty line becomes its own <p>; empty lines produce a
 * blank <p> for visual spacing. Using <p> per line instead of <br>
 * because Workday's editor may strip <br> tags on innerHTML set.
 */
const plainTextToHtml = (text: string): string => {
  return text
    .split("\n")
    .map((line) => `<p>${line.trim() ? escapeHtml(line) : "&nbsp;"}</p>`)
    .join("");
};

/**
 * Insert notes into the rich text editor, using the same approach as
 * the Workday JD import: set innerHTML + dispatch input/change events.
 *
 * Falls back to native setter for plain <textarea> elements.
 */
const insertNotesIntoInput = (el: HTMLElement, text: string): void => {
  el.focus();
  el.click();

  if (el instanceof HTMLTextAreaElement) {
    const nativeSetter = Object.getOwnPropertyDescriptor(
      HTMLTextAreaElement.prototype,
      "value",
    )?.set;

    const newValue = el.value ? `${el.value}\n\n${text}` : text;

    if (nativeSetter) {
      nativeSetter.call(el, newValue);
    } else {
      el.value = newValue;
    }

    // Dispatch a real InputEvent (not bare Event) — Workday checks inputType
    el.dispatchEvent(
      new InputEvent("input", {
        bubbles: true,
        cancelable: false,
        inputType: "insertText",
        data: text,
      }),
    );
    el.dispatchEvent(new Event("change", { bubbles: true }));

    // Also simulate keyboard activity that Workday may listen for
    el.dispatchEvent(new KeyboardEvent("keydown", { bubbles: true, key: " " }));
    el.dispatchEvent(new KeyboardEvent("keyup", { bubbles: true, key: " " }));
  } else {
    // Rich text editor — same approach as JD import (innerHTML + events)
    const html = plainTextToHtml(text);
    const hasExisting = el.textContent?.trim();
    el.innerHTML = hasExisting ? `${el.innerHTML}<p>&nbsp;</p>${html}` : html;

    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }
};

/**
 * Remove all injected button containers. Since buttons are inserted as
 * siblings (not wrappers), removal is simple — no need to restore
 * moved elements.
 */
const cleanUpButton = (): void => {
  document.querySelectorAll(`.${BUTTON_CONTAINER_CLASS}`).forEach((el) => {
    el.remove();
  });
  importButton = null;
};

/**
 * Set button text and disabled state.
 */
const setButtonState = (text: string, disabled: boolean): void => {
  if (!importButton) return;
  const textEl = importButton.querySelector<HTMLElement>(".bh-button-text");
  if (textEl) textEl.innerText = text;
  importButton.disabled = disabled;
};

const resetButton = (): void => {
  if (interviewSelected) {
    setButtonState("Import BrightHire Notes", false);
  } else {
    setButtonState("Select Interview", false);
  }
};

/**
 * Inject a single "Import BrightHire Notes" button as a sibling right
 * after the Description label in the Add Note panel. This avoids wrapping
 * or moving Workday's own DOM nodes, which would trigger MutationSummary loops.
 */
const addImportButton = (headingEl: HTMLElement): void => {
  // Don't add if already present
  if (document.querySelector(`.${BUTTON_CONTAINER_CLASS}`)) return;

  const btnContainer = document.createElement("div");
  btnContainer.className = BUTTON_CONTAINER_CLASS;
  btnContainer.style.display = "block";
  btnContainer.style.marginBottom = "8px";

  importButton = createButton({
    parent: btnContainer,
    text: interviewSelected ? "Import BrightHire Notes" : "Select Interview",
    type: "primary",
    onClick: () => {
      if (!interviewSelected) {
        // Open the BrightHire drawer so the user can pick an interview
        sendMessageWithTabId({ action: "toggleDrawer" });
        return;
      }

      setButtonState("Loading...", true);

      sendMessageWithTabId({
        action: "pullCandidateNotes",
        payload: { tabUrl: window.location.href },
      });
    },
  });

  // Insert below the Description label — no wrapping or moving nodes
  headingEl.insertAdjacentElement("afterend", btnContainer);
};

/**
 * Main page check — find the Description label in the Add Note panel
 * and inject a single button next to it.
 */
const checkPage = (retries = 0): void => {
  // Skip if we're already manipulating the DOM (prevents observer loops)
  if (isUpdatingDom) return;

  // Avoid acting on Rate Interview / Give Feedback task pages
  const rateInterviewPage = document.querySelector(
    '[data-automation-id="rateInterviewInbox"]',
  );
  if (rateInterviewPage) return;

  // If button already exists, nothing to do
  if (document.querySelector(`.${BUTTON_CONTAINER_CLASS}`)) return;

  const descriptionLabel = findDescriptionLabel();

  if (!descriptionLabel && retries < 30) {
    setTimeout(() => checkPage(retries + 1), 500);
    return;
  }

  if (descriptionLabel) {
    isUpdatingDom = true;
    try {
      addImportButton(descriptionLabel);
    } finally {
      isUpdatingDom = false;
    }
  }
};

// Watch for DOM changes that may indicate the Add Note panel appearing
const observer = new MutationSummary({
  callback: () => {
    checkPage();
  },
  queries: [
    { element: '[data-automation-id="workerProfile"]' },
    { element: '[contenteditable="true"]' },
    { element: '[data-automation-id="pageHeaderTitleText"]' },
  ],
});
observer.disconnect();

onDocumentLoaded(() => {
  checkPage();
  observer.reconnect();
});

/**
 * Listen for messages from the service worker / sidepanel.
 */
addPassiveMessageListener(({ message }) => {
  if (message.action === "tabUrlChanged") {
    // On navigation, clean up and re-check
    cleanUpButton();
    checkPage();
  }

  if (message.action === "candidateNotesStatus") {
    interviewSelected = !!message.payload?.hasInterviewSelected;
    resetButton();
  }

  if (message.action === "fillCandidateNotes") {
    const text = message.payload?.candidateNotesText;

    if (!text) {
      // Briefly flash a "no notes" message then reset
      setButtonState("No notes available", true);
      setTimeout(resetButton, 3000);
      return;
    }

    // Find the rich text editor in the Add Note panel
    const input = findNoteInput();

    if (input) {
      insertNotesIntoInput(input, text);
      showConfetti();
    } else {
      setButtonState("No textarea found", true);
      setTimeout(resetButton, 3000);
      return;
    }

    resetButton();
  }
});
